import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

// Hollow County: a compact, systemic first-person horror story.
const $ = (s) => document.querySelector(s);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x171d1e);
scene.fog = new THREE.FogExp2(0x171d1e, 0.012);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 240);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.08;
$('#game').appendChild(renderer.domElement);
const hemi = new THREE.HemisphereLight(0x8997a0, 0x24211c, 1.0); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xa6b2bb, 1.15); moon.position.set(-30, 45, 12); scene.add(moon);
const ambient = new THREE.AmbientLight(0x4c585b, .35); scene.add(ambient);
const flashlight = new THREE.SpotLight(0xd8dfd0, 0, 34, Math.PI / 7, .52, 1.5); flashlight.position.set(0, 0, 0); flashlight.target.position.set(0, 0, -1); camera.add(flashlight, flashlight.target); scene.add(camera);
const clock = new THREE.Clock();
const mats = {};
const mat = (name, color, roughness=1, extra={}) => mats[name] ||= new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const boxGeo = new THREE.BoxGeometry(1,1,1); const sphereGeo = new THREE.SphereGeometry(1, 10, 8);
const world = new THREE.Group(); scene.add(world);
const interactive = [], npcs = [], threats = [], doors = [], clueObjects = [], props = [], rainDrops = [];
const rand = (a,b) => a + Math.random()*(b-a); const pick = a => a[Math.floor(Math.random()*a.length)];
function box(parent, name, x,y,z, sx,sy,sz, material, opts={}) { const mesh=new THREE.Mesh(boxGeo, material); mesh.name=name; mesh.position.set(x,y,z); mesh.scale.set(sx,sy,sz); if(opts.cast!==false)mesh.castShadow=false; mesh.receiveShadow=true; parent.add(mesh); return mesh; }
function addInteract(mesh, data){ mesh.userData.interact=data; interactive.push(mesh); return mesh; }
function floor(parent,x,z,w,d,color=0x343737,y=0){return box(parent,'floor',x,y,z,w,.16,d,mat('floor'+color,color));}
function makeClue(parent, x,y,z, title, body, key, required=false){
 const g=new THREE.Group(); g.position.set(x,y,z); parent.add(g);
 box(g,'paper',0,0,0,.42,.035,.3,mat('paper',0xb7ad94)); box(g,'ink',0,.021,-.035,.25,.006,.02,mat('ink',0x584e42));
 const m=addInteract(g,{type:'clue',title,body,key,required}); clueObjects.push(m); return g;
}
function lamp(x,z){
 const g=new THREE.Group(); g.position.set(x,0,z); world.add(g); box(g,'lamp-post',0,3.2,0,.12,6.4,.12,mat('lampmetal',0x343b3c));
 box(g,'lamp-head',.23,6.27,0,.7,.14,.35,mat('lamphead',0x484b46));
 const l=new THREE.PointLight(0xd3c298,1.4,15,2); l.position.set(.22,6.05,0); g.add(l); props.push({type:'lamp',light:l});
}
function tree(x,z,scale=1){
 const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);world.add(g);
 const bark=mat('bark',0x39362f), leaf=mat('foliage',0x293533);
 const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.16,.3,3.5,6),bark);trunk.position.y=1.75;g.add(trunk);
 for(let i=0;i<3;i++){const c=new THREE.Mesh(new THREE.ConeGeometry(1.15-i*.18,2.4,7),leaf);c.position.set(rand(-.2,.2),3.2+i*.65,rand(-.15,.15));g.add(c);}
}
function building({name,x,z,w=10,d=9,h=7,color=0x57534c,kind='house',locked=false,story=''}){
 const g=new THREE.Group();g.position.set(x,0,z);world.add(g);g.userData={name,kind,locked,story};
 const body=box(g,'building',0,h/2,0,w,h,d,mat('wall'+color,color));
 box(g,'roof',0,h+.12,0,w+.55,.3,d+.55,mat('roof'+color,kind==='industrial'?0x343b3a:0x393a37));
 // front faces the south (-Z for approach from road)
 box(g,'door',0,1.2,-d/2-.05,1.1,2.4,.13,mat('door',0x292b29));
 const door=addInteract(g.children[g.children.length-1],{type:'door',building:g,locked}); doors.push({mesh:door,building:g});
 for(let side of [-1,1]) for(let yy of [2.4,4.7]){
  if(yy>h-1)continue;
  const win=box(g,'window',side*w*.32,yy,-d/2-.08,1.45,1.35,.08,mat('window',Math.random()<.42?0x9b8968:0x283637,.4,{emissive:0x443522,emissiveIntensity:.3}));
  box(g,'sill',side*w*.32,yy-.72,-d/2-.12,1.7,.1,.2,mat('sill',0x393b38));
 }
 // weathering and entry marker
 if(kind==='hospital'||kind==='police'||kind==='school'||kind==='church'){
  const sign=box(g,'sign',0,h+.55,-d/2-.2,Math.min(w-1,6),.42,.12,mat('sign'+name,kind==='hospital'?0x687a73:0x4a4b43));
  const beacon=new THREE.PointLight(kind==='hospital'?0x8eaa9d:0xc38d66,.35,5);beacon.position.set(0,h+.65,-d/2-.35);g.add(beacon);
 }
 // side walls visually break up the mass
 g.userData.dimensions={w,d,h};
 return g;
}
function interior(build, idx){
 const group=new THREE.Group(); scene.add(group);group.position.set((idx-1)*34,-28,0);group.visible=false;
 const w=12, d=12; floor(group,0,0,w,d,0x292c2a,-.12);
 for(const [x,z,sx,sz] of [[0,-6,12,.28],[0,6,12,.28],[-6,0,.28,12],[6,0,.28,12]])box(group,'interior-wall',x,1.9,z,sx,3.8,sz,mat('inside'+idx,0x555148));
 // ceiling lights, furniture, distinct object language per room
 const ceiling=new THREE.PointLight(0xc9ae7e,build.userData.kind==='hospital'?.32:.55,17,2);ceiling.position.set(0,3.2,0);group.add(ceiling);
 box(group,'table',-2,.82,-1,2.7,.18,1.5,mat('wood',0x514438));box(group,'table-leg',-3,.4,-1,.12,.8,.12,mat('wood2',0x38332b));
 box(group,'shelf',3,1.1,-3,2.2,2.2,.45,mat('shelf',0x41403a));
 box(group,'door-mark',0,1.15,5.75,1.15,2.3,.12,mat('exitdoor',0x292b29));
 const exit=addInteract(group.children[group.children.length-1],{type:'exit',building:build,group});
 const type=build.userData.kind;
 if(type==='house'){
  box(group,'bed',2,.4,2,2.8,.65,2.2,mat('bed',0x65645e));
  makeClue(group,-1.7,1.05,-1.1,'Mara’s letter',"Eli—if you still have the key, don't bring it to the house. The water under St. Agnes has started saying my name. I heard it before the sirens. I heard it before Mom went missing.\n\nI left the address where you asked. Come alone. Please.",'letter',true);
  makeClue(group,3.5,.4,-3.1,'A child’s drawing','A careful drawing of four people beneath a black sun. The smallest figure has been scratched away. On the back: “MOM IS IN THE WALL.”','drawing');
 } else if(type==='diner'){
  makeClue(group,-1.6,1.05,-1.1,'Shift ledger','October 17: Mara Venn worked the late shift. She left at 11:40. No one saw her leave. October 18: the same entry, in the same handwriting. The diner was closed.','ledger');
 } else if(type==='police'){
  makeClue(group,-1.6,1.05,-1.1,'Incident report 94-118','Deputy Hale’s report: “No missing person. No disturbance at 14 Bellweather.” A second page is stapled underneath. It lists the same address, the same date, and three names. Every name has been crossed out.','report');
 } else if(type==='hospital'){
  makeClue(group,-1.6,1.05,-1.1,'Intake tape transcript','Patient: Mara Venn. “The thing in the reservoir has my mother’s voice.” Physician: “There is no reservoir beneath St. Agnes.” Patient: “Then why can you hear it too?”','intake');
 } else if(type==='school'){
  makeClue(group,-1.6,1.05,-1.1,'Attendance book','The class photo is dated 1963. The students’ faces have been carefully cut out. A note in the margin reads: “When the bell rings, don’t count the children.”','attendance');
 } else if(type==='church'){
  makeClue(group,-1.6,1.05,-1.1,'Vestry book','A list of names, one per year, beginning in 1948. Beside each: “returned to the water.” The final entry is tomorrow’s date.','vestry');
 } else if(type==='mill'){
  makeClue(group,-1.6,1.05,-1.1,'Maintenance tape','“There’s a service hatch under the old pump room. The town sealed it after the flood. If you hear knocking from below, do not knock back.”','tape');
 } else {
  makeClue(group,-1.6,1.05,-1.1,'Unsent postcard','The postcard is addressed to no one. “The map is wrong. The streets don’t lead out anymore. I walked east for six hours and came back to the school.”','postcard');
 }
 build.userData.room=group; build.userData.door=exit;
 return group;
}

// A walkable town grid: the same routes are familiar in daylight and wrong after dark.
const ground=new THREE.Mesh(new THREE.PlaneGeometry(190,190),mat('earth',0x353934));ground.rotation.x=-Math.PI/2;ground.position.y=-.12;world.add(ground);
for(let v=-75;v<=75;v+=25){
 box(world,'asphalt',v,.005,0,7,.05,180,mat('road',0x292f30));box(world,'asphalt',0,.006,v,180,.05,7,mat('road',0x292f30));
 for(let t=-80;t<=80;t+=8){box(world,'road-mark',v,.04,t, .11,.012,3.1,mat('mark',0x827d6a));box(world,'road-mark',t,.04,v,3.1,.012,.11,mat('mark',0x827d6a));}
}
// side streets, sidewalks, hedges, power poles
for(let i=-3;i<=3;i++) for(let j=-3;j<=3;j++){
 const bx=i*25, bz=j*25;
 box(world,'sidewalk',bx+7,.03,bz+7,10,.12,10,mat('sidewalk',0x454846));
 if(Math.abs(bx)>58||Math.abs(bz)>58)continue;
 if(Math.random()<.54){tree(bx+rand(-9,9),bz+rand(-9,9),rand(.8,1.3));}
 if(Math.random()<.25)lamp(bx+(Math.random()<.5?-5:5),bz+(Math.random()<.5?-5:5));
}
const places=[];
const place=(o,idx)=>{const b=building(o);places.push(b);interior(b,idx);return b;};
const mara=place({name:'14 Bellweather House',x:-9,z:-17,w:9,d:8,h:6.5,color:0x625e54,kind:'house'},0);
const market=place({name:'County Market',x:13,z:-17,w:12,d:10,h:6,color:0x666253,kind:'shop',story:'The checkout scanner is still on. It keeps reading the same item.'},1);
const diner=place({name:'The Last Stop Diner',x:19,z:-39,w:12,d:9,h:6,color:0x71624d,kind:'diner'},2);
const police=place({name:'County Sheriff',x:-14,z:-42,w:12,d:10,h:7,color:0x535b58,kind:'police',locked:true},3);
const hospital=place({name:'St. Agnes Hospital',x:-39,z:-37,w:15,d:12,h:10,color:0x73766e,kind:'hospital',locked:true},4);
const school=place({name:'Bellweather Elementary',x:-43,z:13,w:15,d:12,h:8,color:0x766c5b,kind:'school',locked:true},5);
const church=place({name:'St. Oran’s Church',x:39,z:-39,w:12,d:12,h:10,color:0x5e5c54,kind:'church'},6);
const motel=place({name:'Pine Rest Motor Lodge',x:15,z:39,w:14,d:9,h:5,color:0x6a5948,kind:'motel'},7);
const mill=place({name:'Ashdown Paper Mill',x:43,z:39,w:15,d:13,h:11,color:0x484c48,kind:'industrial',locked:true},8);
// distant structures, water tower, cemetery wall, utility yard, forest edge
building({name:'Bellweather Apartments',x:42,z:10,w:13,d:12,h:13,color:0x575955,kind:'apartments'});
building({name:'Abandoned Clinic',x:-48,z:40,w:10,d:10,h:6,color:0x444945,kind:'abandoned'});
box(world,'water-tower',-30,15,51,2,18,2,mat('tower',0x444d4b));const tank=new THREE.Mesh(new THREE.CylinderGeometry(4,4,5,12),mat('tank',0x505857));tank.position.set(-30,25,51);world.add(tank);
for(let i=0;i<18;i++){const x=rand(-68,68),z=rand(65,84);tree(x,z,rand(.8,1.7));tree(x,-z,rand(.8,1.6));tree(z,x,rand(.8,1.5));tree(-z,x,rand(.8,1.5));}
// cemetery: crooked headstones, one open grave and a bell that moves on windless nights
for(let i=0;i<13;i++){const x=30+(i%5)*2.1,z=-55+Math.floor(i/5)*2.6;box(world,'headstone',x,.55,z,.8,1.1,.2,mat('stone',0x62615a)).rotation.z=rand(-.15,.15);}
box(world,'grave',36,.05,-56,2.4,.15,4,mat('soil',0x282522));
// the service hatch in the woods appears as an ordinary storm drain until the town is ready
const hatch=box(world,'storm-drain',0,.15,63,2.3,.22,1.7,mat('drain',0x343a38));addInteract(hatch,{type:'hatch'});
// interior-specific investigation objects
for(const b of places){const room=b.userData.room; const exit=b.userData.door; exit.userData.interact={type:'exit',building:b,group:room};}

function createNPC(name, role, x,z, personality, routine, color=0x6a7471){
 const g=new THREE.Group();g.position.set(x,0,z);world.add(g);
 const coat=mat('npc'+name,color), skin=mat('skin'+name,0x968276), dark=mat('npcdark'+name,0x272b2a);
 const body=new THREE.Mesh(new THREE.CylinderGeometry(.28,.36,1.15,7),coat);body.position.y=1.05;g.add(body);
 const head=new THREE.Mesh(sphereGeo,skin);head.scale.set(.24,.3,.23);head.position.y=1.82;g.add(head);
 const hair=new THREE.Mesh(sphereGeo,dark);hair.scale.set(.25,.15,.25);hair.position.set(0,2.03,-.01);g.add(hair);
 g.userData={name,role,personality,routine,trust:0,met:false,phase:Math.random()*6,home:new THREE.Vector3(x,0,z),speed:rand(.35,.8),g,baseColor:color};
 npcs.push(g);return g;
}
createNPC('Ruth Bell','DINER OWNER',18,-29,'kind, watchful',['diner','church','home'],0x72594d);
createNPC('Deputy Hale','SHERIFF',-14,-34,'rigid, evasive',['police','diner','home'],0x536461);
createNPC('Eli Venn','MISSING BOY?',-32,17,'quiet, observant',['school','motel','woods'],0x596a70);
createNPC('Mrs. Kessler','NEIGHBOR',-17,-13,'lonely, superstitious',['house','market','church'],0x82776b);
createNPC('The Night Clerk','MOTEL CLERK',12,33,'polite, exhausted',['motel','motel','home'],0x626159);
createNPC('A Man in a Work Coat','MILL WORKER',37,31,'angry, frightened',['mill','diner','woods'],0x454f4e);
// narrative stains and evidence: uneasy, non-graphic environmental detail
for(let i=0;i<7;i++){const stain=new THREE.Mesh(new THREE.CircleGeometry(rand(.2,.7),12),mat('rust'+i,0x422b27));stain.rotation.x=-Math.PI/2;stain.position.set(rand(-45,45),.035,rand(-55,55));world.add(stain);}
for(let i=0;i<4;i++){const clue=makeClue(world,rand(-53,53),.12,rand(-48,52),pick(['A wet footprint','A torn photograph','A voicemail slip','A church notice']),pick(['The ink is blurred, but your name is still legible.','Someone circled the date of tomorrow.','The paper smells faintly of lake water.','The message ends with a second voice breathing.']),`outdoor-${i}`);clue.rotation.y=rand(0,Math.PI);}
// A threat is built but withheld from sight until the player's nerve or the hour gives it permission.
function createThreat(){const g=new THREE.Group();const cloak=mat('entity',0x111515,.8,{emissive:0x090d0d,emissiveIntensity:.3});
 const torso=new THREE.Mesh(new THREE.CylinderGeometry(.25,.48,1.9,7),cloak);torso.position.y=1.2;g.add(torso);
 const head=new THREE.Mesh(sphereGeo,mat('entity-head',0x161b1b));head.scale.set(.29,.38,.28);head.position.y=2.35;g.add(head);
 for(let s of [-1,1]){const limb=new THREE.Mesh(new THREE.CylinderGeometry(.08,.11,1.15,5),cloak);limb.position.set(s*.46,1.15,.08);limb.rotation.z=s*.16;g.add(limb);}
 g.visible=false;world.add(g);g.userData={active:false,phase:Math.random()*9,seen:0,attack:0};threats.push(g);return g;}
createThreat();
const rainGroup=new THREE.Group();scene.add(rainGroup);const rainGeo=new THREE.BufferGeometry();const rainPos=new Float32Array(500*3);for(let i=0;i<500;i++){rainPos[i*3]=rand(-22,22);rainPos[i*3+1]=rand(0,16);rainPos[i*3+2]=rand(-22,22);}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:0x9ca8a7,size:.045,transparent:true,opacity:.35}));rainGroup.add(rain);

const state={started:false,paused:false,inside:null,returnPos:null,returnYaw:0,yaw:0,pitch:0,health:100,nerve:84,stamina:100,hunger:88,thirst:91,flashlight:true,ammo:72,inventory:{'Field notebook':1,'Flashlight':1,'Painkillers':1,'Canned peaches':1,'Alcohol wipes':0,'Clean cloth':0},clues:[],flags:{},relationships:{},time:18*60+42,weather:'FOG',weatherTimer:90,eventTimer:35,steps:0,crouch:false,dead:false,ending:false};
const player=new THREE.Vector3(0,0,10), velocity=new THREE.Vector3(), keys={};
const todays=['THU, OCT 23','FRI, OCT 24','SAT, OCT 25'];
function setPrompt(text){const p=$('#prompt');if(text){p.classList.remove('hidden');p.innerHTML=`<kbd>E</kbd><span>${text}</span>`;}else p.classList.add('hidden');}
function toast(text,ms=3600){const el=$('#event-toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),ms);}
function whisper(text){const el=$('#whisper');el.textContent=text;el.classList.add('show');clearTimeout(whisper.timer);whisper.timer=setTimeout(()=>el.classList.remove('show'),4200);}
function showPanel(kicker,title,html){$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-content').innerHTML=html;$('#panel').classList.remove('hidden');state.paused=true;document.exitPointerLock?.();}
function closePanel(){ $('#panel').classList.add('hidden');state.paused=false;if(state.started&&!state.dead&&innerWidth>700)renderer.domElement.requestPointerLock?.(); }
$('#close-panel').addEventListener('click',closePanel);$('#panel').addEventListener('click',e=>{if(e.target.id==='panel')closePanel();});
function cluePanel(clue){
 if(!state.clues.includes(clue.key)){state.clues.push(clue.key);state.flags[clue.key]=true;state.nerve=Math.max(0,state.nerve-(clue.required?2:1));
  if(clue.key==='letter')state.objective='Ask Ruth at the Last Stop about Mara’s last shift.';
  if(clue.key==='ledger')state.objective='Take Ruth’s lead to Deputy Hale at the Sheriff’s office.';
  if(clue.key==='report')state.objective='Find out what St. Agnes did to Mara.';
  if(clue.key==='intake')state.objective='The mill tape mentioned a service hatch in the woods.';
  if(clue.key==='tape')state.objective='Find the storm drain beyond the water tower.';
  if(clue.key==='vestry')state.objective='You have enough. Decide what the town deserves.';
 }
 const count=state.clues.length;
 const extra=clue.key==='letter'?'<div class="clue">NEW LEAD &nbsp;·&nbsp; RUTH BELL SAW MARA THAT NIGHT</div>':clue.key==='report'?'<div class="clue">KEY FOUND &nbsp;·&nbsp; ST. AGNES SIDE DOOR</div>':'';
 showPanel('FOUND EVIDENCE',clue.title,`<p>${clue.body.replaceAll('\n\n','</p><p>')}</p>${extra}<div class="clue">EVIDENCE ${count.toString().padStart(2,'0')} &nbsp; / &nbsp; 9 KNOWN THREADS</div>`);
 updateObjective();
}
function updateObjective(){ $('#objective-text').textContent=state.objective||'Follow the town’s quiet hours.'; }
function doorCheck(b){
 const k=b.userData.kind;
 if(!b.userData.locked)return true;
 const needs={police:'letter',school:'ledger',hospital:'report',industrial:'intake'}[k];
 if(needs&&state.clues.includes(needs)){b.userData.locked=false;return true;}
 if(needs==='letter'&&!state.clues.includes(needs))toast('LOCKED — THE LETTER MAY SAY WHO HAS A KEY.');
 else if(needs==='ledger'&&!state.clues.includes(needs))toast('LOCKED — ASK AROUND TOWN.');
 else if(needs==='report'&&!state.clues.includes(needs))toast('LOCKED — A DEPUTY’S KEY IS NEEDED.');
 else if(needs==='intake'&&!state.clues.includes(needs))toast('LOCKED — THE HOSPITAL HAS THE MILL KEY.');
 return false;
}
function enterBuilding(b){if(!doorCheck(b))return;
 state.returnPos=player.clone();state.returnYaw=state.yaw;state.inside=b;world.visible=false;b.userData.room.visible=true;
 const off=b.userData.room.position;player.set(off.x,0,4.35);state.yaw=Math.PI;toast(b.userData.name.toUpperCase());
}
function leaveBuilding(b){b.userData.room.visible=false;world.visible=true;state.inside=null;player.copy(state.returnPos||new THREE.Vector3(0,0,10));state.yaw=state.returnYaw;toast('OUTSIDE. THE STREET LOOKS DIFFERENT.');}
function addItem(name,n=1){state.inventory[name]=(state.inventory[name]||0)+n;toast(`ADDED TO PACK  ·  ${name.toUpperCase()}`);}
function interactObject(obj){const d=obj.userData.interact;if(!d)return;
 if(d.type==='clue'){if(d.key.startsWith('outdoor')&&state.clues.includes(d.key)){toast('ONLY THE WET PAPER REMAINS.');return;}cluePanel(d);return;}
 if(d.type==='door'){enterBuilding(d.building);return;}
 if(d.type==='exit'){leaveBuilding(d.building);return;}
 if(d.type==='hatch'){
  if(!state.clues.includes('tape')){toast('A heavy iron cover. Something knocks once from below.');state.nerve-=4;return;}
  if(!state.flags.hatchOpen){state.flags.hatchOpen=true;toast('THE BOLTS TURN WITHOUT A SOUND.');return;}
  if(!state.flags.endgame){state.flags.endgame=true;openEndingChoice();return;}
 }
 if(d.type==='supply'){if(state.flags[d.id]){toast('EMPTY.');return;}state.flags[d.id]=true;addItem(d.item,d.amount||1);}
}
function openEndingChoice(){
 showPanel('BELOW BELLWEATHER','The water is listening',`<p>At the bottom of the service stairs, the town opens into a chamber that should not fit beneath it. The walls are wet. Your mother’s voice comes from somewhere behind them.</p><p>There is a brass wheel, a telephone with its receiver off the hook, and a narrow door with warm light beneath it. You recognize all three sounds. None of the memories are yours.</p><button class="choice" data-end="seal">TURN THE WHEEL — seal the flooded chamber. No one else should hear it.</button><button class="choice" data-end="answer">PICK UP THE RECEIVER — ask the voice what it wants.</button><button class="choice" data-end="leave">TAKE THE LIT DOOR — leave the town with what you know.</button>`);
 $('#panel-content').querySelectorAll('[data-end]').forEach(btn=>btn.onclick=()=>finishEnding(btn.dataset.end));
}
