function openJournal(){const clues=state.clues.map((c,i)=>`<p><span class="clue">${String(i+1).padStart(2,'0')} &nbsp; ${c.toUpperCase().replaceAll('-',' ')}</span></p>`).join('');const people=npcs.map(n=>`<p><b>${n.userData.name}</b> — ${n.userData.met?'you have spoken.':'not yet met.'} ${n.userData.trust>1?'They trust you.':n.userData.trust<0?'They do not trust you.':''}</p>`).join('');showPanel('FIELD NOTES · NIGHT '+(Math.floor(state.time/1440)+1),'What the town left behind',`<p><b>Current lead</b><br>${state.objective}</p><p><b>Evidence collected · ${state.clues.length}/9</b></p>${clues||'<p>Your notebook is dry and blank.</p>'}<div class="clue">PEOPLE WHO REMEMBER YOU</div>${people}<div class="clue">TAB OR Q TO CLOSE · CRAFT BANDAGE: C</div>`);}
