 const ctx=new AC();state.audio=ctx;const master=ctx.createGain();master.gain.value=.18;master.connect(ctx.destination);
 const osc=ctx.createOscillator(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();osc.type='triangle';osc.frequency.value=47;filter.type='lowpass';filter.frequency.value=105;gain.gain.value=.09;osc.connect(filter);filter.connect(gain);gain.connect(master);osc.start();state.drone={gain,master,ctx};
 const lfo=ctx.createOscillator(),lg=ctx.createGain();lfo.frequency.value=.13;lg.gain.value=8;lfo.connect(lg);lg.connect(osc.frequency);lfo.start();
}
function soundPulse(freq=150,duration=.3,volume=.12){if(!state.audio)return;const c=state.audio;const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(freq,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.55),c.currentTime+duration);g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(state.drone.master);o.start();o.stop(c.currentTime+duration);}
function noiseSound(){if(!state.audio)return;const c=state.audio;const n=c.createBufferSource(),buffer=c.createBuffer(1,c.sampleRate*1.1,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/data.length,2);n.buffer=buffer;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=520;const g=c.createGain();g.gain.value=.055;n.connect(f);f.connect(g);g.connect(state.drone.master);n.start();}
