const raycaster=new THREE.Raycaster();
function nearestInteraction(){
 const origin=camera.position, dir=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);let best=null,bestDist=4.2,bestScore=99;
 for(const o of interactive){if(!o.visible&&!o.parent.visible)continue;const p=new THREE.Vector3();o.getWorldPosition(p);const dist=p.distanceTo(origin);if(dist>4.5||dist<.1)continue;
  const delta=p.sub(origin).normalize(),dot=dir.dot(delta);const score=dist+(1-dot)*2.1;if(dot>.08&&score<bestScore){best=o;bestScore=score;bestDist=dist;}}
 for(const n of npcs){if(!n.visible)continue;const p=n.position.clone().add(new THREE.Vector3(0,1.3,0));const dist=p.distanceTo(origin);const dot=dir.dot(p.sub(origin).normalize());const score=dist+(1-dot)*2;if(dist<3.6&&dot>.15&&score<bestScore){best=n;bestScore=score;bestDist=dist;}}
 return best;
}
function resolvePosition(x,z){
 // The streets stay open; architecture and the town boundary have collision.
 const px=x,pz=z;
 if(!state.inside){
  x=Math.max(-88,Math.min(88,x));z=Math.max(-88,Math.min(88,z));
  for(const b of places.concat([])){
   const dx=Math.abs(x-b.position.x),dz=Math.abs(z-b.position.z),dim=b.userData.dimensions;
   if(dx<dim.w/2+.5&&dz<dim.d/2+.5){if(Math.abs(px-b.position.x)>dim.w/2+.5)x=px;else if(Math.abs(pz-b.position.z)>dim.d/2+.5)z=pz;else if(dx/dim.w>dz/dim.d) x=b.position.x+Math.sign(x-b.position.x)*(dim.w/2+.5);else z=b.position.z+Math.sign(z-b.position.z)*(dim.d/2+.5);}
  }
  for(const n of npcs){if(n.position.distanceTo(new THREE.Vector3(x,0,z))<.7){x=px;z=pz;}}
 }else{
  const off=state.inside.userData.room.position;const lx=x-off.x,lz=z-off.z;
