 const move=dir.multiplyScalar(fwd).add(right.multiplyScalar(side));if(move.lengthSq()>1)move.normalize();
 const [nx,nz]=resolvePosition(player.x+move.x*speed*dt,player.z+move.z*speed*dt);player.x=nx;player.z=nz;
 const bob=moving?Math.sin(performance.now()*(running?.013:.009))*(running?.045:.018):0;
 camera.position.set(player.x,player.y+1.62+bob,player.z);camera.rotation.order='YXZ';camera.rotation.set(state.pitch,state.yaw,0);
