function keyDown(e){if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(!state.started||state.dead)return;
 if(e.code==='KeyE'||e.code==='Space'){if(!state.paused){const o=nearestInteraction();if(o){if(o.userData?.interact)interactObject(o);else talkTo(o);}}}
 if(e.code==='KeyQ'||e.code==='Tab'){if(!state.paused){e.preventDefault();openJournal();}else if(!$('#panel').classList.contains('hidden'))closePanel();}
 if(e.code==='KeyI'){if(!state.paused)openInventory();else if(!$('#panel').classList.contains('hidden'))closePanel();}
 if(e.code==='KeyF'&&!state.paused){state.flashlight=!state.flashlight;toast(state.flashlight?'FLASHLIGHT ON':'FLASHLIGHT OFF');updateBars();}
 if(e.code==='KeyC'&&!state.paused){state.crouch=!state.crouch;updateBars();}
 if(e.code==='KeyE'&&state.paused&&$('#panel').classList.contains('hidden'))state.paused=false;
 if(e.code==='Escape'&&state.paused&&!$('#panel').classList.contains('hidden'))closePanel();
 if(e.code==='KeyC'&&e.shiftKey)craftBandage();
}
function keyUp(e){keys[e.code]=false;}window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);

