63: function damage(amount,reason){state.health=Math.max(0,state.health-amount);$('#damage-flash').style.opacity='.38';setTimeout(()=>$('#damage-flash').style.opacity='0',130);soundPulse(78,.35,.16);if(reason)toast(reason);if(state.health<=0)die();updateBars();}
64: function die(){state.dead=true;state.paused=true;document.exitPointerLock?.();$('#death-title').textContent=pick(['The town went quiet.','No one heard you leave.','The lights stayed on.']);$('#death-copy').textContent='The rain stops. At the county line, a telephone rings beneath the road. You do not answer.\n\n'+state.clues.length+' pieces of evidence found · '+Object.values(state.relationships).filter(v=>v>0).length+' residents trusted you.';$('#death-screen').classList.remove('hidden');}
65: function craftBandage(){if((state.inventory['Clean cloth']||0)>0&&(state.inventory['Alcohol wipes']||0)>0){state.inventory['Clean cloth']--;state.inventory['Alcohol wipes']--;state.health=Math.min(100,state.health+24);toast('A ROUGH BANDAGE. IT WILL HAVE TO DO.');updateBars();}else toast('NEED CLEAN CLOTH + ALCOHOL WIPES.');}
66: function keyDown(e){if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(!state.started||state.dead)return;
67:  if(e.code==='KeyE'||e.code==='Space'){if(!state.paused){const o=nearestInteraction();if(o){if(o.userData?.interact)interactObject(o);else talkTo(o);}}}
68:  if(e.code==='KeyQ'||e.code==='Tab'){if(!state.paused){e.preventDefault();openJournal();}else if(!$('#panel').classList.contains('hidden'))closePanel();}
69:  if(e.code==='KeyI'){if(!state.paused)openInventory();else if(!$('#panel').classList.contains('hidden'))closePanel();}
70:  if(e.code==='KeyF'&&!state.paused){state.flashlight=!state.flashlight;toast(state.flashlight?'FLASHLIGHT ON':'FLASHLIGHT OFF');updateBars();}
71:  if(e.code==='KeyC'&&!state.paused){state.crouch=!state.crouch;updateBars();}
72:  if(e.code==='KeyE'&&state.paused&&$('#panel').classList.contains('hidden'))state.paused=false;
73:  if(e.code==='Escape'&&state.paused&&!$('#panel').classList.contains('hidden'))closePanel();
74:  if(e.code==='KeyC'&&e.shiftKey)craftBandage();
75: }
76: function keyUp(e){keys[e.code]=false;}window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);

