// HOLLOW COUNTY — The Quiet Hours. A compact, replayable first-person horror game.
const $ = (s) => document.querySelector(s);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x171d1e);
scene.fog = new THREE.FogExp2(0x171d1e, 0.0105);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 220);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.6));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.12;
$('#game').appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0x89969a, 0x29251f, 1.15));
const moon = new THREE.DirectionalLight(0xb4bbb0, 1.05); moon.position.set(-25, 45, 20); scene.add(moon);
const fill = new THREE.AmbientLight(0x4c5554, .45); scene.add(fill);
const flashlight = new THREE.SpotLight(0xe0e4d6, 0, 36, Math.PI / 7, .55, 1.4);
camera.add(flashlight, flashlight.target); scene.add(camera);
const clock = new THREE.Clock();
const mat = (color, roughness=1, extra={}) => new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const boxGeo = new THREE.BoxGeometry(1,1,1), sphereGeo = new THREE.SphereGeometry(1, 10, 8);
const world = new THREE.Group(); scene.add(world);
const interactives=[], buildings=[], npcs=[], lamps=[], clues=[], threats=[];
const rand=(a,b)=>a+Math.random()*(b-a), pick=a=>a[Math.floor(Math.random()*a.length)];
const state={started:false,paused:false,inside:null,returnPos:null,returnYaw:0,yaw:0,pitch:0,health:100,nerve:84,stamina:100,hunger:88,flashlight:true,battery:72,inventory:{'Field notebook':1,'Flashlight':1,'Painkillers':1,'Canned peaches':1,'Alcohol wipes':0,'Clean cloth':0},evidence:[],flags:{},relations:{},time:18*60+42,weather:'FOG',weatherTimer:75,eventTimer:26,crouch:false,dead:false,ending:false};
const player=new THREE.Vector3(0,0,9), keys={};
function meshBox(parent,name,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(boxGeo,material);m.name=name;m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.receiveShadow=true;parent.add(m);return m;}
function addInteract(mesh,data){mesh.userData.interact=data;interactives.push(mesh);return mesh;}
function toast(text,ms=3400){const e=$('#event-toast');e.textContent=text;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),ms);}
function whisper(text){const e=$('#whisper');e.textContent=text;e.classList.add('show');clearTimeout(whisper.timer);whisper.timer=setTimeout(()=>e.classList.remove('show'),4200);}
function showPanel(kicker,title,html){$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-content').innerHTML=html;$('#panel').classList.remove('hidden');state.paused=true;document.exitPointerLock?.();}
function closePanel(){ $('#panel').classList.add('hidden');state.paused=false;if(state.started&&!state.dead&&innerWidth>700)renderer.domElement.requestPointerLock?.();}
$('#close-panel').addEventListener('click',closePanel);
$('#panel').addEventListener('click',e=>{if(e.target.id==='panel')closePanel();});
function createClue(parent,x,y,z,title,text,id){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);meshBox(g,'paper',0,0,0,.42,.035,.3,mat(0xb8ad94));meshBox(g,'writing',0,.022,-.03,.25,.006,.02,mat(0x554b3c));const m=addInteract(g,{type:'clue',title,text,id});clues.push(m);return m;}
function tree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(s);world.add(g);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.15,.28,3.3,6),mat(0x39362f));trunk.position.y=1.65;g.add(trunk);for(let i=0;i<3;i++){const c=new THREE.Mesh(new THREE.ConeGeometry(1.25-i*.2,2.4,7),mat(0x293532));c.position.y=3+i*.7;g.add(c);}}
function streetlamp(x,z){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);meshBox(g,'post',0,3.1,0,.12,6.2,.12,mat(0x343a39));meshBox(g,'lamphead',.22,6.15,0,.65,.15,.3,mat(0x4a4b43));const l=new THREE.PointLight(0xd5c59b,1.3,15,2);l.position.set(.2,5.95,0);g.add(l);lamps.push(l);}
function makeBuilding(data,index){
 const g=new THREE.Group();g.position.set(data.x,0,data.z);world.add(g);g.userData={...data,locked:!!data.locked};
 meshBox(g,'building',0,data.h/2,0,data.w,data.h,data.d,mat(data.color));meshBox(g,'roof',0,data.h+.12,0,data.w+.45,.28,data.d+.45,mat(0x393a37));
 const door=meshBox(g,'entry',0,1.15,-data.d/2-.07,1.05,2.3,.16,mat(0x292c2a));addInteract(door,{type:'door',building:g});
 for(const side of [-1,1])for(const y of [2.4,4.6])if(y<data.h-.6){meshBox(g,'window',side*data.w*.32,y,-data.d/2-.08,1.4,1.2,.08,mat(Math.random()<.4?0x877b65:0x263334,.55,{emissive:0x483a22,emissiveIntensity:.3}));}
 const room=new THREE.Group();room.position.set(120+index*32,-25,0);room.visible=false;scene.add(room);
 meshBox(room,'room-floor',0,-.08,0,12,.16,12,mat(0x323331));
 for(const [x,z,sx,sz] of [[0,-6,12,.28],[0,6,12,.28],[-6,0,.28,12],[6,0,.28,12]])meshBox(room,'interior-wall',x,1.9,z,sx,3.8,sz,mat(data.interiorColor||0x555148));
 const light=new THREE.PointLight(data.kind==='hospital'?0xb9c7bc:0xc9ae7e,.72,18,2);light.position.set(0,3.2,0);room.add(light);
 meshBox(room,'table',-2,.82,-1,2.7,.18,1.5,mat(0x514438));meshBox(room,'shelf',3,1.1,-3,2.2,2.2,.45,mat(0x41403a));meshBox(room,'bed',2,.4,2,2.8,.65,2.2,mat(0x66625c));
 const exit=meshBox(room,'exit',0,1.15,5.72,1.2,2.3,.14,mat(0x292c2a));addInteract(exit,{type:'exit',building:g});
 const evidence=data.evidence||{title:'Unsent note',text:'The ink is blurred, but your name is still legible.',id:data.kind};
 createClue(room,-1.7,1.05,-1.1,evidence.title,evidence.text,evidence.id);
 if(data.kind==='house')createClue(room,3.4,.4,-3.1,'A child’s drawing','Four figures beneath a black sun. The smallest has been scratched away. “MOM IS IN THE WALL.”','drawing');
 g.userData.room=room;g.userData.dimensions={w:data.w,d:data.d};buildings.push(g);return g;
}

