// Roads, neighborhoods, forest edge, and recognizable town landmarks.
const ground=new THREE.Mesh(new THREE.PlaneGeometry(190,190),mat(0x363a35));ground.rotation.x=-Math.PI/2;ground.position.y=-.14;world.add(ground);
for(let v=-75;v<=75;v+=25){meshBox(world,'road',v,.005,0,7,.05,180,mat(0x292f30));meshBox(world,'road',0,.006,v,180,.05,7,mat(0x292f30));for(let t=-80;t<=80;t+=8){meshBox(world,'road-mark',v,.04,t,.11,.012,3,mat(0x827d6a));meshBox(world,'road-mark',t,.04,v,3,.012,.11,mat(0x827d6a));}}
for(let i=-3;i<=3;i++)for(let j=-3;j<=3;j++){const x=i*25,z=j*25;meshBox(world,'sidewalk',x+7,.03,z+7,10,.12,10,mat(0x454846));if(Math.random()<.57)tree(x+rand(-9,9),z+rand(-9,9),rand(.8,1.3));if(Math.random()<.22)streetlamp(x+(Math.random()<.5?-5:5),z+(Math.random()<.5?-5:5));}
const places=[];
const place=(d,i)=>{const b=makeBuilding(d,i);places.push(b);return b;};
const mara=place({name:'14 Bellweather House',kind:'house',x:-9,z:-17,w:9,d:8,h:6.5,color:0x625e54,evidence:{title:'Mara’s letter',text:'Eli—if you still have the key, don’t bring it to the house. The water under St. Agnes has started saying my name. I heard it before the sirens. I left the address where you asked. Come alone. Please.','id':'letter'}},0);
place({name:'County Market',kind:'shop',x:13,z:-17,w:12,d:10,h:6,color:0x666253,evidence:{title:'Checkout slip',text:'A receipt dated tomorrow. One item: “ONE RETURN.” It has been paid in cash.','id':'receipt'}},1);
place({name:'The Last Stop Diner',kind:'diner',x:19,z:-39,w:12,d:9,h:6,color:0x71624d,evidence:{title:'Shift ledger',text:'October 17: Mara Venn worked the late shift. She left at 11:40. October 18: the same entry, same handwriting. The diner was closed.','id':'ledger'}},2);
place({name:'County Sheriff',kind:'police',x:-14,z:-42,w:12,d:10,h:7,color:0x535b58,locked:true,evidence:{title:'Incident report 94-118',text:'Deputy Hale’s report: “No missing person. No disturbance at 14 Bellweather.” A second page lists three names. Each has been crossed out.','id':'report'}},3);
place({name:'St. Agnes Hospital',kind:'hospital',x:-39,z:-37,w:15,d:12,h:10,color:0x73766e,locked:true,evidence:{title:'Intake transcript',text:'Patient: Mara Venn. “The thing in the reservoir has my mother’s voice.” Physician: “There is no reservoir beneath St. Agnes.” Patient: “Then why can you hear it too?”','id':'intake'}},4);
place({name:'Bellweather Elementary',kind:'school',x:-43,z:13,w:15,d:12,h:8,color:0x766c5b,evidence:{title:'Attendance book',text:'A class photo dated 1963. The students’ faces have been cut out. “When the bell rings, don’t count the children.”','id':'attendance'}},5);
place({name:'St. Oran’s Church',kind:'church',x:39,z:-39,w:12,d:12,h:10,color:0x5e5c54,evidence:{title:'Vestry book',text:'A list of names, one per year, beginning in 1948. Beside each: “returned to the water.” The final entry is tomorrow’s date.','id':'vestry'}},6);
place({name:'Pine Rest Motor Lodge',kind:'motel',x:15,z:39,w:14,d:9,h:5,color:0x6a5948,evidence:{title:'Unsent postcard',text:'“The map is wrong. The streets don’t lead out anymore. I walked east for six hours and came back to the school.”','id':'postcard'}},7);
place({name:'Ashdown Paper Mill',kind:'industrial',x:43,z:39,w:15,d:13,h:11,color:0x484c48,locked:true,evidence:{title:'Maintenance tape',text:'“There’s a service hatch under the old pump room. The town sealed it after the flood. If you hear knocking from below, do not knock back.”','id':'tape'}},8);
makeBuilding({name:'Bellweather Apartments',kind:'apartments',x:42,z:10,w:13,d:12,h:13,color:0x575955,evidence:{title:'Tenant list',text:'The directory has one name: MARA VENN. The ink is still wet.','id':'tenant'}},9);
makeBuilding({name:'Abandoned Clinic',kind:'abandoned',x:-48,z:40,w:10,d:10,h:6,color:0x444945,evidence:{title:'Patient card',text:'The name field is blank. The photograph is you, taken from behind.','id':'patient'}},10);
const tower=new THREE.Mesh(new THREE.CylinderGeometry(4,4,5,12),mat(0x505857));tower.position.set(-30,25,51);world.add(tower);meshBox(world,'tower-support',-30,15,51,2,18,2,mat(0x444d4b));
for(let i=0;i<16;i++){const x=rand(-68,68),z=rand(65,84);tree(x,z,rand(.8,1.5));tree(x,-z,rand(.8,1.5));tree(z,x,rand(.8,1.4));tree(-z,x,rand(.8,1.4));}
for(let i=0;i<13;i++){const x=30+(i%5)*2.1,z=-55+Math.floor(i/5)*2.6;meshBox(world,'headstone',x,.55,z,.8,1.1,.2,mat(0x62615a));}
const hatch=meshBox(world,'storm-drain',0,.12,68,2.4,.22,1.8,mat(0x343a38));addInteract(hatch,{type:'hatch'});
// An autonomous-feeling town: residents drift between a few routine destinations and remember choices.
function createNPC(name,role,x,z,personality,color){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);const coat=mat(color),skin=mat(0x968276),dark=mat(0x272b2a);const body=new THREE.Mesh(new THREE.CylinderGeometry(.28,.36,1.15,7),coat);body.position.y=1.05;g.add(body);const head=new THREE.Mesh(sphereGeo,skin);head.scale.set(.24,.3,.23);head.position.y=1.82;g.add(head);const hair=new THREE.Mesh(sphereGeo,dark);hair.scale.set(.25,.15,.25);hair.position.set(0,2.03,-.01);g.add(hair);g.userData={name,role,personality,trust:0,met:false,phase:rand(0,8),home:new THREE.Vector3(x,0,z),speed:rand(.3,.65),target:new THREE.Vector3(x,0,z)};npcs.push(g);return g;}
