function initAudio(){if(audio)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audio=new AC();const master=audio.createGain();master.gain.value=.12;master.connect(audio.destination);const osc=audio.createOscillator(),gain=audio.createGain(),filter=audio.createBiquadFilter();osc.type='triangle';osc.frequency.value=47;filter.type='lowpass';filter.frequency.value=130;gain.gain.value=.22;osc.connect(filter).connect(gain).connect(master);osc.start();audioNodes={master,gain,osc,filter};}
function tone(freq=220,duration=.22,volume=.05){if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
function updateBars(){ $('#health-fill').style.width=`${state.health}%`;$('#health-value').textContent=Math.round(state.health);$('#nerve-fill').style.width=`${state.nerve}%`;$('#nerve-value').textContent=Math.round(state.nerve);$('#ammo-count').textContent=`BATTERY ${Math.round(state.battery)}%`;$('#equipped-name').textContent=state.flashlight?'FLASHLIGHT':'EMPTY HANDS';$('#equipped-icon').textContent=state.flashlight?'◉':'∅';$('#status-text').textContent=`${state.weather} / ${state.crouch?'CROUCHED':((keys.ShiftLeft||keys.ShiftRight)?'RUNNING':'WALKING')}`;}
