function addEvidence(data){if(state.evidence.some(e=>e.id===data.id)){toast('You already recorded this evidence.');return;}state.evidence.push({id:data.id,title:data.title,text:data.text});tone(520,.15,.035);toast(`EVIDENCE ADDED — ${data.title}`);if(data.id==='letter'){state.flags.letter=true;setObjective('Ask the people at the diner and sheriff’s office about Mara.');}if(state.evidence.length>=3&&!state.flags.key){state.flags.lead=true;setObjective('Find Eli Venn near the school. He knows what the key opens.');}if(state.evidence.length>=5)setObjective('Find the service hatch at the north edge of town.');}
