function panelButton(label,action,disabled=false){return `<button class="choice${disabled?' disabled':''}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;}
function inventoryPanel(){const rows=Object.entries(state.inventory).filter(([,n])=>n>0).map(([name,n])=>`<div class="item-row"><span>${name}</span><b>× ${n}</b></div>`).join('')||'<p>Your pockets are empty.</p>';showPanel('PACK & FIELD KIT','What you carried in',`<div class="item-list">${rows}</div><p class="muted">A little preparation can keep the dark at arm’s length.</p>${panelButton('TAKE PAINKILLERS · restore health','painkillers',!state.inventory['Painkillers'])}${panelButton('EAT CANNED PEACHES · restore nerve','peaches',!state.inventory['Canned peaches'])}${panelButton('CRAFT · alcohol wipes + clean cloth = first aid','craft',!(state.inventory['Alcohol wipes']&&state.inventory['Clean cloth']))}`);}
function journalPanel(){const evidence=state.evidence.length?state.evidence.map(e=>`<article class="evidence-entry"><b>${e.title}</b><p>${e.text}</p></article>`).join(''):'<p>No evidence yet. Look closely at papers, objects, and people.</p>';showPanel('FIELD NOTES',`${state.evidence.length} piece${state.evidence.length===1?'':'s'} of evidence`,`${evidence}<hr><p><b>Leads</b><br>${$('#objective-text').textContent}</p><p class="muted">Evidence changes what the town is willing to tell you.</p>`);}
function enterBuilding(b){if(b.userData.locked){let can=false;if(b.userData.kind==='police'&&(state.flags.letter||state.flags.ruth))can=true;if(b.userData.kind==='hospital'&&(state.flags.key||state.flags.hale))can=true;if(b.userData.kind==='industrial'&&state.evidence.length>=4)can=true;if(!can){toast(b.userData.kind==='police'?'The station is locked. Ruth might know why Hale is avoiding you.':b.userData.kind==='hospital'?'The doors are chained. Find Eli and ask about his key.':'The mill gate is sealed. You need more of the town’s story.');return;}b.userData.locked=false;}
