function dialogue(n){const d=n.userData;let text='',choices=[];if(d.name==='Ruth Bell'){text=d.met?'“People come in here every night asking about a girl who was never missing.”':'“You’re Mara’s brother. I remember you. You used to sit by the window and count headlights.”';choices=[['Ask about Mara','ruth-mara'],['Ask about Deputy Hale','ruth-hale'],['Offer the letter','ruth-letter']];}
 else if(d.name==='Deputy Hale'){text=d.met?'“I told you. No missing person. No report.”':'“The county line’s closed tonight. You should go back the way you came.”';choices=[['Ask about incident 94-118','hale-report'],['Show Mara’s letter','hale-letter'],['Ask for the hospital key','hale-key']];}
 else if(d.name==='Eli Venn'){text=d.met?'“She said you’d come back. She said you wouldn’t remember me.”':'“You’re looking for Mara. You have her eyes. I kept the key like she asked.”';choices=[['Ask what happened to Mara','eli-mara'],['Ask about the key','eli-key'],['Tell him you remember','eli-remember']];}
 else if(d.name==='Mrs. Kessler'){text=d.met?'“Still hearing the pipes sing, dear?”':'“After the flood they bricked up the reservoir. My husband heard knocking from under the church for years.”';choices=[['Ask about the flood','kessler-flood'],['Ask about the reservoir','kessler-reservoir']];}
 else if(d.name==='The Night Clerk'){text='“Room 6 checked in yesterday. Nobody’s been there in twenty years. Key’s still on the hook.”';choices=[['Ask about the guestbook','clerk-book'],['Take the first-aid supplies','clerk-supplies']];}
 else {text='“You can still leave. Before the bell rings, I mean.”';choices=[['Ask about the mill','worker-mill'],['Ask about the service hatch','worker-hatch']];}
 d.met=true;const opts=choices.map(([label,action])=>panelButton(label,action)).join('');showPanel(d.role,d.name,`<p class="dialogue">${text}</p>${opts}<p class="muted">Your choices are remembered.</p>`);state.activeNPC=n;}
function action(action){const n=state.activeNPC,flag=(k)=>state.flags[k]=true;switch(action){case'ruth-mara':flag('ruth');state.relations.ruth=(state.relations.ruth||0)+1;toast('Ruth’s expression softens.');break;case'ruth-hale':flag('ruth');toast('“He keeps the station report in his desk.”');break;case'ruth-letter':if(state.flags.letter){flag('ruth');toast('Ruth reads it twice. “The night she vanished, I heard the sirens too.”');}else toast('You need to find Mara’s letter first.');break;case'hale-report':if(state.flags.letter||state.flags.ruth){addEvidence({id:'report',title:'Incident report 94-118',text:'Hale’s report says no one disappeared. The attached page is a list of names, one crossed out in fresh ink: Mara Venn.'});flag('hale');places.find(b=>b.userData.kind==='police').userData.locked=false;}else toast('Hale turns away. Bring him something that proves you knew Mara.');break;case'hale-letter':if(state.flags.letter){flag('hale');toast('“I never saw this.” He slips a brass key across the desk.');state.flags.key=true;state.inventory['Brass key']=1;places.find(b=>b.userData.kind==='hospital').userData.locked=false;}else toast('You have no letter to show him.');break;case'hale-key':if(state.flags.ruth||state.flags.letter){flag('key');state.flags.key=true;state.inventory['Brass key']=1;places.find(b=>b.userData.kind==='hospital').userData.locked=false;toast('Hale gives you the hospital key.');}else toast('He refuses.');break;case'eli-mara':if(state.evidence.length>=1){flag('eli');toast('“She went below St. Agnes. She said the water knew our names.”');}else toast('“Find her letter first. It’s at the house.”');break;case'eli-key':if(state.flags.letter||state.evidence.length>=3){flag('key');state.flags.eli=true;state.inventory['Brass key']=1;places.find(b=>b.userData.kind==='hospital').userData.locked=false;toast('Eli presses the cold key into your palm. “Not for a door.”');}else toast('Eli watches you silently.');break;case'eli-remember':state.nerve=Math.min(100,state.nerve+8);flag('eli');whisper('“You promised you would come back for me.”');break;case'kessler-flood':flag('flood');addEvidence({id:'flood',title:'Mrs. Kessler’s account',text:'In 1963 the reservoir flooded the basement at St. Agnes. The county sealed its lower level and called the deaths an accident.'});break;case'kessler-reservoir':flag('reservoir');whisper('“The church well is older than the town. Older than the county.”');break;case'clerk-book':flag('motel');addEvidence({id:'guestbook',title:'Motel guestbook',text:'Room 6 has been booked under your name every October 23 since 1963.'});break;case'clerk-supplies':if(!state.flags.supplies){state.flags.supplies=true;state.inventory['Alcohol wipes']=1;state.inventory['Clean cloth']=1;toast('You found alcohol wipes and a clean cloth.');}else toast('The supply drawer is empty.');break;case'worker-mill':flag('mill');toast('“We shut it down when the pipes started knocking.”');break;case'worker-hatch':flag('hatchLead');toast('“North road, beyond the water tower. But don’t answer it.”');break;case'painkillers':state.inventory['Painkillers']--;state.health=Math.min(100,state.health+38);tone(300,.2,.04);toast('Pain fades.');closePanel();return;case'peaches':state.inventory['Canned peaches']--;state.nerve=Math.min(100,state.nerve+28);state.hunger=Math.min(100,state.hunger+30);toast('Sweetness, from another life.');closePanel();return;case'craft':state.inventory['Alcohol wipes']--;state.inventory['Clean cloth']--;state.inventory['First aid kit']=(state.inventory['First aid kit']||0)+1;toast('Crafted a first aid kit. Use it from your pack.');break;case'firstaid':state.inventory['First aid kit']--;state.health=Math.min(100,state.health+55);closePanel();return;case'end-truth':finishEnding('truth');return;case'end-rescue':finishEnding('rescue');return;case'end-bury':finishEnding('bury');return;}
 if(action==='craft'&&state.inventory['First aid kit']){$('#panel-content').insertAdjacentHTML('beforeend',panelButton('USE FIRST AID KIT · restore health','firstaid'));}if(n)dialogue(n);else if(action==='ending'){endingPanel();}}
function endingPanel(){state.paused=true;const canTruth=state.evidence.some(e=>e.id==='report'||e.id==='intake')&&state.evidence.some(e=>e.id==='letter');const canRescue=state.flags.key||state.inventory['Brass key'];showPanel('THE SERVICE HATCH','The water is listening',`<p class="dialogue">A black stairwell descends beneath the road. From below: Mara’s voice, then a child’s, then your own.</p>${panelButton('CALL THE COUNTY · expose what happened','end-truth',!canTruth)}${panelButton('GO DOWN ALONE · bring Mara home','end-rescue',!canRescue)}${panelButton('SEAL THE HATCH · leave the dead below','end-bury')}<p class="muted">Different truths lead to different endings.</p>`);}
function finishEnding(type){state.ending=true;state.paused=true;document.exitPointerLock?.();$('#panel').classList.add('hidden');const details={truth:['THE COUNTY HEARS YOU','By morning, the report is everywhere. No one remembers writing it. The reservoir answers the sirens.'],rescue:['SOMEONE COMES BACK','You find Mara beneath the hospital. She knows your name. Outside, the town has forgotten yours.'],bury:['THE QUIET HOURS','You bury the key and seal the hatch. For one year, Bellweather sleeps. Then the knocking begins again.']}[type];$('#death-title').textContent=details[0];$('#death-copy').textContent=details[1];$('#restart-button').textContent='RETURN TO THE COUNTY ↗';$('#death-screen').classList.remove('hidden');}
