function interact(){if(!nearest)return;const d=nearest.userData.interact;if(d.type==='clue'){if(d.id==='tape')state.flags.tape=true;addEvidence(d);}else if(d.type==='door'){const from=nearest.parent;const front=from.localToWorld(new THREE.Vector3(0,0,-1));const delta=player.clone().sub(front);if(delta.length()<2.4){enterBuilding(d.building);}else toast(`Approach ${d.building.userData.name} from the street.`);}else if(d.type==='exit')exitBuilding();else if(d.type==='hatch'){if(state.evidence.length<3&&!state.flags.key){toast('The hatch is sealed. You need more evidence and a key.');return;}endingPanel();}else if(d.type==='npc')dialogue(d.npc);}
function findNearest(){nearest=null;let best=3.0;const look=new THREE.Vector3();camera.getWorldDirection(look);for(const obj of interactives){let visible=true;for(let parent=obj;parent;parent=parent.parent)if(!parent.visible){visible=false;break;}if(!visible)continue;const p=new THREE.Vector3();obj.getWorldPosition(p);const dist=p.distanceTo(camera.position);if(dist<.25||dist>best)continue;const dir=p.sub(camera.position).normalize();if(look.dot(dir)<.35)continue;best=dist;nearest=obj;}const prompt=$('#prompt');if(nearest){const d=nearest.userData.interact;let label='INTERACT';if(d.type==='door')label=d.building.userData.name.toUpperCase();if(d.type==='clue')label=`READ ${d.title.toUpperCase()}`;if(d.type==='npc')label=`TALK TO ${d.npc.userData.name.toUpperCase()}`;if(d.type==='exit')label='LEAVE BUILDING';if(d.type==='hatch')label='OPEN SERVICE HATCH';prompt.innerHTML=`<kbd>E</kbd><span>${label}</span>`;prompt.classList.remove('hidden');}else prompt.classList.add('hidden');}
