function onKeyDown(e){keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!state.started||state.dead||state.ending)return;if(e.repeat)return;if(e.code==='KeyE'||e.code==='Space')interact();if(e.code==='KeyF')toggleFlashlight();if(e.code==='KeyC'&&!e.shiftKey){state.crouch=!state.crouch;toast(state.crouch?'You crouch low.':'You stand.');}if(e.code==='KeyC'&&e.shiftKey)useKit();if(e.code==='KeyI')inventoryPanel();if(e.code==='KeyJ'||e.code==='KeyQ'||e.code==='Tab')journalPanel();if(e.code==='Escape'&&!$('#panel').classList.contains('hidden'))closePanel();if(e.code==='Escape'&&$('#panel').classList.contains('hidden')){state.paused=!state.paused;toast(state.paused?'PAUSED':'');}}
